/**
 * FeatureImportancePremium.js - Enhanced SHAP Feature Importance
 * With animated gradient bars
 */

import React from 'react';
import { motion } from 'framer-motion';

const FeatureImportancePremium = ({ features }) => {
  const maxImpact = Math.max(...features.map(f => Math.abs(f.impact)));

  return (
    <div className="glass-card feature-card-premium">
      <h3 className="section-title">
        <span className="icon">🔑</span>
        <span>Key Influencing Features</span>
      </h3>

      <div className="feature-list-premium">
        {features.map((feature, index) => {
          const isPositive = feature.impact > 0;
          const absImpact = Math.abs(feature.impact);
          const percentage = (absImpact / maxImpact) * 100;

          return (
            <motion.div
              key={feature.name}
              className="feature-item-premium"
              initial={{ opacity: 0, x: -30 }}
              animate={{ opacity: 1, x: 0 }}
              transition={{ duration: 0.5, delay: index * 0.1 }}
              whileHover={{ scale: 1.02, x: 5 }}
            >
              <div className="feature-header-premium">
                <div className="feature-rank">{index + 1}</div>
                <div className="feature-name-premium">{feature.name}</div>
                <div className={`feature-badge ${isPositive ? 'bullish' : 'bearish'}`}>
                  {isPositive ? '↗️ Bullish' : '↘️ Bearish'}
                </div>
              </div>

              <div className="feature-bar-container">
                <motion.div
                  className={`feature-bar-premium ${isPositive ? 'positive' : 'negative'}`}
                  initial={{ width: 0 }}
                  animate={{ width: `${percentage}%` }}
                  transition={{ duration: 1, delay: 0.5 + index * 0.1, ease: "easeOut" }}
                >
                  <div className="feature-bar-glow" />
                </motion.div>
              </div>

              <div className="feature-impact-value">
                Impact: {feature.impact.toFixed(4)}
              </div>
            </motion.div>
          );
        })}
      </div>

      <div className="feature-tip">
        <span className="tip-icon">💡</span>
        <span className="tip-text">
          Positive impacts suggest upward movement, negative suggest downward
        </span>
      </div>
    </div>
  );
};

export default FeatureImportancePremium;
